// Convert pan (-1 to +1) to angle (0 to π/2)
float angle = (pan + 1.0) * 0.25 * π;
leftGain = cos(angle);
rightGain = sin(angle);

// Convert L/R to M/S
mid = (L + R) * 0.5;    // Mono sum
side = (L - R) * 0.5;   // Stereo difference

// Scale side by width
side *= width;  // 0.0 = mono, 1.0 = normal, 2.0 = wide

// Convert back to L/R
L = mid + side;
R = mid - side;
